// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzz: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a reasonable range
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy a callee that WILL revert on receiving funds to simulate failing transfer
        Reverter rev = new Reverter();

        // fund depositor so they can call payable addToBalance
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // now we want depositor to be the recipient of withdrawBalance; we'll make depositor be the reverter contract
        // so call withdrawBalance from the reverter (msg.sender == reverter) -> but reverter must call into c
        // We need the reverter to call c.withdrawBalance() so msg.sender in c is the reverter contract which will revert on receiving

        // Transfer the reverter contract the role of depositor in c's mapping by depositing from reverter
        // First, fund the reverter so it can call addToBalance
        vm.deal(address(rev), 0); // ensure reverter has zero, we will not deposit from it

        // Instead, we simulate that the depositor address is the reverter by directly calling addToBalance from rev
        // So reset: deposit from rev
        // Make sure rev has funds
        vm.deal(address(rev), amount);
        vm.prank(address(rev));
        c.addToBalance{value: amount}();

        // sanity: getBalance(rev) == amount on the reference contract
        uint256 balBefore = c.getBalance(address(rev));
        // must be amount
        assert(balBefore == amount);

        // Now attempt withdrawBalance called by rev; the reverter's receive will revert when c sends value
        bool ok;
        try rev.callWithdraw(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: on the correct contract, when the external transfer to msg.sender fails, the call to withdrawBalance reverts (so ok == false) and the contract preserves the user's balance.
        // We assert that either the withdraw reverted (ok == false) AND balance still equals original amount, OR (if it somehow succeeded) balance is zero.
        // For the correct contract, the failing transfer causes a revert, so ok must be false and balance unchanged.

        // Read the current recorded balance
        uint256 balAfter = c.getBalance(address(rev));

        // Single assertion: the correct contract always leaves balance unchanged when the outgoing transfer to msg.sender fails (i.e., the withdraw call does not succeed), and the mutant that ignores transfer failure will produce ok==true with balance==0 for some inputs; hence we assert that if the withdraw did not succeed then the balance remains equal to before.
        assertTrue((ok == false && balAfter == balBefore));
    }
}

// Adversarial helper that calls withdrawBalance on C and reverts when receiving funds
contract Reverter {
    // call withdraw on target C
    function callWithdraw(address target) external {
        Reentrance(target).withdrawBalance();
    }

    // Revert on receiving Ether to simulate failing transfer
    receive() external payable {
        revert("force revert");
    }
}
